/// 🎯️ Resolves an editor edit into concrete kind mutations: row-id removals (nested rows addressed by their parent selectors) first, every other path through [`EDIT_RULES`].
pub fn resolve_edit(document: &En1999Snapshot, edit: &NormEdit) -> Result<Vec<En1999Mutation>, String> {
    EDIT_RULES.resolve_with_id_removals(ID_REMOVALS, document, edit)
}

/// 🧭️ Resolves every editor edit through the typed [`EDIT_RULES`]: one kind per leaf, no whole-collection fallback.
pub fn resolve(document: &En1999Snapshot, edit: &NormEdit) -> Result<Vec<En1999Mutation>, String> {
    resolve_edit(document, edit)
}

